from cfnlint.template.transforms._language_extensions import (
    _ForEachValueFnFindInMap,
    _ResolveError,
    get_hash,
)

def _make_cfn(mappings: dict, parameters: dict | None = None) -> Template:
    template = {
        "Mappings": mappings,
        "Parameters": parameters or {},
        "Resources": {},
    }
    return Template("", template)

